WITH art_score AS (
    SELECT AVG(CASE WHEN shipment_overview->'route'->>'risk_note' = 'Low' THEN 8.0 WHEN shipment_overview->'route'->>'risk_note' = 'Medium' THEN 5.0 WHEN shipment_overview->'route'->>'risk_note' = 'High' THEN 2.0 ELSE 4.0 END) as avg_art FROM shipments
),
rrd_score AS (
    SELECT AVG(CASE WHEN carriercert = 'Both' THEN 10.0 WHEN carriercert IN ('GDP', 'CEIV Pharma') THEN 8.0 ELSE 4.0 END) as avg_rrd FROM carriers
),
sbp_score AS (
    SELECT AVG(CASE WHEN veh_qual = 'Validated' THEN 9.0 WHEN veh_qual = 'Qualified' THEN 7.0 ELSE 5.0 END) as avg_sbp FROM vehicles
),
smc_score AS (
    SELECT AVG(CASE WHEN qc_checklist->'gdp_quality'->>'gdp_compliance' = 'Full' THEN 9.0 WHEN qc_checklist->'gdp_quality'->>'gdp_compliance' = 'Partial' THEN 6.0 ELSE 3.0 END) as avg_smc FROM qualitycompliance
)
SELECT a.avg_art, r.avg_rrd, s.avg_sbp, m.avg_smc, 
       ROUND(CAST((0.4 * a.avg_art + 0.3 * r.avg_rrd + 0.2 * s.avg_sbp + 0.1 * m.avg_smc) AS numeric), 2) as resilience_score
FROM art_score a, rrd_score r, sbp_score s, smc_score m;

SELECT ROUND((
    0.4 * (SELECT AVG(CASE WHEN shipment_overview->'route'->>'risk_note' = 'Low' THEN 8.0 WHEN shipment_overview->'route'->>'risk_note' = 'Medium' THEN 5.0 WHEN shipment_overview->'route'->>'risk_note' = 'High' THEN 2.0 ELSE 4.0 END) FROM shipments) +
    0.3 * (SELECT AVG(CASE WHEN carriercert = 'Both' THEN 10.0 WHEN carriercert IN ('GDP', 'CEIV Pharma') THEN 8.0 ELSE 4.0 END) FROM carriers) +
    0.2 * (SELECT AVG(CASE WHEN veh_qual = 'Validated' THEN 9.0 WHEN veh_qual = 'Qualified' THEN 7.0 ELSE 5.0 END) FROM vehicles) +
    0.1 * (SELECT AVG(CASE WHEN qc_checklist->'gdp_quality'->>'gdp_compliance' = 'Full' THEN 9.0 WHEN qc_checklist->'gdp_quality'->>'gdp_compliance' = 'Partial' THEN 6.0 ELSE 3.0 END) FROM qualitycompliance)
)::numeric, 2) as resilience_score;

